INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "李嗣周三万禁军送徐彦若，屯兴平", "start_year": 893, "end_year": 893, "time_original": "893年九月乙亥", "dynasty": "唐", "description": "李嗣周率三万禁军送徐彦若赴凤翔节度使之任，军队驻兴平。李茂贞、王行瑜合近六万军屯盩厔拒之。", "phases": [], "location_name": "兴平、凤翔", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "a51f3109-6a4c-55be-ba5e-c08994540c57"}, {"title": "李茂贞王行瑜逼兴平，禁军溃、进三桥", "start_year": 893, "end_year": 893, "time_original": "893年九月壬午", "dynasty": "唐", "description": "《通鉴》述禁军皆新募市井少年、邠岐军为久战边兵。壬午李茂贞等逼兴平，禁军望风溃逃，邠岐军乘胜攻三桥，京师震动，士民逃散，市人守阙请诛最先议战者。", "phases": [], "location_name": "兴平、三桥、京师", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "21effbc7-a125-5b0a-81ff-27c67dca2f0a"}, {"title": "崔昭纬密书归责杜让能，李茂贞表请诛", "start_year": 893, "end_year": 893, "time_original": "893年九月；甲申李陈临皋表请", "dynasty": "唐", "description": "崔昭纬嫉害杜让能，密信李茂贞称用兵不是皇帝意思而全由杜。甲申李茂贞陈兵临皋驿，上表列杜让能罪，请杀之。", "phases": [], "location_name": "京师、临皋驿", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "ee1b1d65-1dfb-52eb-8ec9-bf6e794011fe"}, {"title": "杜让能请自任罪，贬梧州并命流三宦官", "start_year": 893, "end_year": 893, "time_original": "893年九月甲申", "dynasty": "唐", "description": "杜让能请求以自己解难，昭宗流泪诀别，贬其为梧州刺史，制词称其弃善谋而构藩镇衅。又命西门君遂流儋州、李周潼流崖州、段诩流欢州。", "phases": [], "location_name": "京师；梧州、儋州、崖州、欢州（所命贬流地）", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "bb810b61-b2a5-5e64-8173-f58f6630e3ad"}, {"title": "昭宗安福门斩三人，再贬杜让能雷州", "start_year": 893, "end_year": 893, "time_original": "893年九月乙酉", "dynasty": "唐", "description": "昭宗到安福门，斩西门君遂、李周潼、段诩，再贬杜让能为雷州司户。派使向李茂贞称惑帝举兵的是这三人，不是杜之罪。", "phases": [], "location_name": "京师、安福门；雷州（所命贬地）", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e1c10de6-81f0-5a29-b971-31526fe0fec7"}, {"title": "骆全瓘刘景宣授左右军中尉", "start_year": 893, "end_year": 893, "time_original": "乙酉条后；893年九月，具体日未载", "dynasty": "唐", "description": "朝廷任内侍骆全瓘、刘景宣为左右军中尉。", "phases": [], "location_name": "京师", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "26804892-1cc4-5e10-ba48-1bf644b1c9e7"}, {"title": "韦昭度、崔胤授同平章事", "start_year": 893, "end_year": 893, "time_original": "893年九月壬辰", "dynasty": "唐", "description": "朝廷以东都留守韦昭度为司徒、门下侍郎、同平章事，以御史中丞崔胤为户部侍郎、同平章事。", "phases": [], "location_name": "京师", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "bd20ce48-22fe-53d5-a179-31c07711b063"}, {"title": "崔安潜忧崔胤将毁门户", "start_year": null, "end_year": null, "time_original": "崔胤授相条所附；言说具体年日未载", "dynasty": "唐", "description": "崔安潜对亲近者说，父兄刻苦建立家门，终将被缁郎崔胤败坏。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "eca552bd-da93-5ef4-8e46-10b11174b012"}, {"title": "李茂贞不解兵，崔昭纬挤杜让能", "start_year": 893, "end_year": 893, "time_original": "九月贬杜后至冬十月之前条", "dynasty": "唐", "description": "李茂贞不撤兵，要求杀杜让能才回镇，崔昭纬继续协助排挤杜。", "phases": [], "location_name": "临皋、京师", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "843686eb-bc10-536a-8137-3d2869678bba"}, {"title": "杜让能杜弘徽获赐自尽", "start_year": 893, "end_year": 893, "time_original": "893年冬十月；具体日未载", "dynasty": "唐", "description": "朝廷赐杜让能及其弟户部侍郎杜弘徽自尽。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "0caacc9f-618d-5113-9755-136de4d50efc"}, {"title": "朝廷诏称杜让能枉法卖官聚敛", "start_year": 893, "end_year": 893, "time_original": "赐自尽后条；具体日未载", "dynasty": "唐", "description": "朝廷再诏告中外，称杜让能举枉错直、爱憎徇一时、卖官鬻狱、聚敛巨万。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "62ba81c6-6b0a-5a78-ae7b-1a21a7e3142c"}, {"title": "邠岐判官崔鋋王超助二镇干预朝廷总述", "start_year": null, "end_year": null, "time_original": "自是；后续各次确年日未载", "dynasty": "唐", "description": "《通鉴》述此后朝廷动息都禀邠岐，南北司往往依附两镇求恩。两镇判官崔鋋、王超受不满者诉告，教李茂贞、王行瑜上章干预，朝廷稍不从便言辞不逊。", "phases": [], "location_name": "邠、岐、朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "c0fde460-92f3-5962-aa49-98c7f5864633"}, {"title": "李茂贞复授凤翔兼山南，徐彦若御史大夫", "start_year": 893, "end_year": 893, "time_original": "893年冬十月条；具体日未载", "dynasty": "唐", "description": "朝廷再以李茂贞为凤翔节度使兼山南西道节度使、守中书令；书述他由此尽有凤翔、兴元、洋、陇秦等十五州之地。徐彦若任御史大夫。", "phases": [], "location_name": "凤翔、山南西道、兴元等十五州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "948116f6-f266-5b75-b1a0-1676b9a6f04d"}, {"title": "王潮授福建观察使", "start_year": 893, "end_year": 893, "time_original": "893年十月戊戌", "dynasty": "唐", "description": "朝廷以泉州刺史王潮为福建观察使。", "phases": [], "location_name": "福建、泉州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "f807ab23-2560-5fe0-b499-6314e84000a1"}, {"title": "倪章弃舒州，杨行密以李神福为刺史", "start_year": 893, "end_year": 893, "time_original": "893年十月条；具体日未载", "dynasty": "唐", "description": "舒州刺史倪章弃城逃走，杨行密以李神福为舒州刺史。", "phases": [], "location_name": "舒州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "87b1c5ab-2397-51cb-980e-deb00c66c2a3"}, {"title": "王行瑜求尚书令，韦昭度密谏", "start_year": 893, "end_year": 893, "time_original": "893年十一月之前条；具体日未载", "dynasty": "唐", "description": "王行瑜求任尚书令，韦昭度密奏称太宗以此职执政后登大位，此后不授人臣，仅郭子仪以大功受授仍终身避让，王行瑜不可轻议。", "phases": [], "location_name": "朝廷、邠宁", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "35c3efcd-9be6-58df-8c41-a37c0f014592"}, {"title": "王行瑜授太师、号尚父、赐铁券", "start_year": 893, "end_year": 893, "time_original": "893年十一月", "dynasty": "唐", "description": "朝廷授王行瑜太师，赐号尚父并赐铁券。", "phases": [], "location_name": "邠宁、朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e8f4aa59-5aee-5bc6-9b98-d81ca989ea50"}, {"title": "朱全忠请徙盐铁汴州，朝廷诏谕", "start_year": 893, "end_year": 893, "time_original": "893年十二月", "dynasty": "唐", "description": "朱全忠请求把盐铁事务移至汴州方便供军。崔昭纬担忧朱新破徐郓而兵力倍增，若再掌盐铁便难控制，朝廷遂诏开谕。", "phases": [], "location_name": "汴州、朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e1ffbbd1-89de-562e-9d75-998a68adb270"}, {"title": "葛从周攻齐州，朱瑄朱瑾救朱威", "start_year": 893, "end_year": 893, "time_original": "893年十二月条；具体日未载", "dynasty": "唐", "description": "汴将葛从周攻齐州刺史朱威，朱瑄、朱瑾率兵来救。", "phases": [], "location_name": "齐州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "bdbc3b00-4df8-5f29-a3ce-a9fd36b91086"}, {"title": "周岳攻取潭州，黄皓杀闵勖后亦被杀", "start_year": 886, "end_year": 886, "time_original": "光启二年六月条；具体日未载", "dynasty": "唐", "description": "衡州刺史周岳攻潭州。钦化节度使闵勖邀黄皓入城共守，黄皓杀闵勖；周岳攻下城，擒杀黄皓。", "phases": [], "location_name": "潭州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "4f3cba00-2f71-55eb-841f-3f7b568235fd"}, {"title": "邓处讷闻闵勖死，誓报仇练兵", "start_year": null, "end_year": null, "time_original": "初；此前闻闵死后，训练八年；具体起讫未载", "dynasty": "唐", "description": "邵州刺史邓处讷听说闵勖被杀而哭，向来吊将领说同受闵恩、欲以一州力报仇，众赞同，于是训练士卒，书载八年。", "phases": [], "location_name": "邵州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "a7426f4e-5c38-5fb5-a8cc-8c11a75c29f6"}, {"title": "邓处讷联雷满克潭斩周岳，自称留后", "start_year": 893, "end_year": 893, "time_original": "893年条段末；练兵八年之后，具体日未载", "dynasty": "唐", "description": "邓处讷联结朗州刺史雷满共攻潭州，攻克并杀周岳，邓自称留后。", "phases": [], "location_name": "潭州、朗州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "fd2361f2-7dc1-5665-8e05-70679a33ca28"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person_relationship (id, person_a, person_b, relation_type, description, status)
SELECT id, person_a, person_b, relation_type, description, status FROM jsonb_populate_recordset(NULL::public.person_relationship, '[{"relation_type": "父亲", "description": "《通鉴》称崔胤为慎由之子；崔慎由是崔胤的父亲。", "status": "draft", "id": "461de1c0-4611-50b1-9da2-278bd782fdab", "person_a": "8affad68-f521-5797-9836-653550779fa7", "person_b": "b071b1d3-7e73-526b-8e08-d1abf5ed205f"}, {"relation_type": "季父", "description": "《通鉴》称安潜为崔胤季父；崔安潜是崔胤的季父，保留具体叔辈称谓。", "status": "draft", "id": "2e650eb7-9303-5e0f-992a-069443822192", "person_a": "500c310b-03c2-59e0-bd61-2cbd4c3588da", "person_b": "b071b1d3-7e73-526b-8e08-d1abf5ed205f"}, {"relation_type": "兄长", "description": "原文称弘徽为杜让能之弟；杜让能是杜弘徽的兄长。", "status": "draft", "id": "e8ac050b-709b-5d09-8692-e13f965ed8c5", "person_a": "e3eae55f-2032-5c76-905f-e480ad32ea69", "person_b": "8e7c5682-1dee-5dcf-a6e8-512190520d63"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

