SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "李嗣周率三万禁军送徐彦若赴凤翔节度使之任，军队驻兴平。李茂贞、王行瑜合近六万军屯盩厔拒之。", "citation": "卷259·景福二年（893）·zztj-v259-y0893-p030·原文件第83行", "note": "原文：乙亥，覃王嗣周帅禁军三万送凤翔节度使徐彦若赴镇，军于兴平。李茂贞、王行瑜合兵近六万，军于盩厔以拒之。禁军皆新募市井少年，茂贞、行瑜所将皆边兵百战之馀，壬午，茂贞等进逼兴平，禁军皆望风逃溃，茂贞等乘胜进攻三桥，京城大震，士民奔散，市人复守阙请诛首议用兵者。崔昭纬心害太尉、门下侍郎、同平章事杜让能，密遗茂贞书曰：“用兵非主上意，皆出于杜太尉耳。”甲申，茂贞陈于临皋驿，表让能罪，请诛之。让能言于上曰：“臣固先言之矣，请以臣为解。”上涕下不自禁，曰：“与卿诀矣！”是日，贬让能梧州刺史，制辞略曰：“弃卿士之臧谋，构籓垣之深衅，咨询之际，证执弥坚。”又流观军容使西门君遂于儋州，内枢密使李周潼于崖州，段诩于欢州。乙酉，上御安福门，斩君遂、周潼、诩，再贬让能雷州司户。遣使谓茂贞曰：“惑朕举兵者，三人也，非让能之罪。”以内侍骆全瓘、刘景宣为左右军中尉。；核对说明：三万近六万为书载，徐未抵凤翔，不記到任；盩厔保留旧地名，不核现代坐标。", "status": "draft", "id": "a6dc5905-ca73-520c-adaa-af38b570d18a", "subject_id": "a51f3109-6a4c-55be-ba5e-c08994540c57", "source_id": "11259805-3f07-5bc8-abc5-ffdc4ecb7b11"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "893年九月乙亥", "citation": "卷259·景福二年（893）·zztj-v259-y0893-p030·原文件第83行", "note": "原文：乙亥，覃王嗣周帅禁军三万送凤翔节度使徐彦若赴镇，军于兴平。李茂贞、王行瑜合兵近六万，军于盩厔以拒之。禁军皆新募市井少年，茂贞、行瑜所将皆边兵百战之馀，壬午，茂贞等进逼兴平，禁军皆望风逃溃，茂贞等乘胜进攻三桥，京城大震，士民奔散，市人复守阙请诛首议用兵者。崔昭纬心害太尉、门下侍郎、同平章事杜让能，密遗茂贞书曰：“用兵非主上意，皆出于杜太尉耳。”甲申，茂贞陈于临皋驿，表让能罪，请诛之。让能言于上曰：“臣固先言之矣，请以臣为解。”上涕下不自禁，曰：“与卿诀矣！”是日，贬让能梧州刺史，制辞略曰：“弃卿士之臧谋，构籓垣之深衅，咨询之际，证执弥坚。”又流观军容使西门君遂于儋州，内枢密使李周潼于崖州，段诩于欢州。乙酉，上御安福门，斩君遂、周潼、诩，再贬让能雷州司户。遣使谓茂贞曰：“惑朕举兵者，三人也，非让能之罪。”以内侍骆全瓘、刘景宣为左右军中尉。；核对说明：三万近六万为书载，徐未抵凤翔，不記到任；盩厔保留旧地名，不核现代坐标。", "status": "draft", "id": "2809587c-8815-56c8-ace8-95fa16160dd0", "subject_id": "a51f3109-6a4c-55be-ba5e-c08994540c57", "source_id": "11259805-3f07-5bc8-abc5-ffdc4ecb7b11"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记李嗣周：以覃王嗣周名领禁军者。", "citation": "卷259·景福二年（893）·zztj-v259-y0893-p030·原文件第83行", "note": "原文：乙亥，覃王嗣周帅禁军三万送凤翔节度使徐彦若赴镇，军于兴平。李茂贞、王行瑜合兵近六万，军于盩厔以拒之。禁军皆新募市井少年，茂贞、行瑜所将皆边兵百战之馀，壬午，茂贞等进逼兴平，禁军皆望风逃溃，茂贞等乘胜进攻三桥，京城大震，士民奔散，市人复守阙请诛首议用兵者。崔昭纬心害太尉、门下侍郎、同平章事杜让能，密遗茂贞书曰：“用兵非主